import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"交易怎么才能找到个师父带一带？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/交易怎么才能找到个师父带一带.md","filePath":"stock/交易认知/交易怎么才能找到个师父带一带.md"}'),r={name:"stock/交易认知/交易怎么才能找到个师父带一带.md"};function _(s,p,n,c,i,d){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="交易怎么才能找到个师父带一带" tabindex="-1">交易怎么才能找到个师父带一带？ <a class="header-anchor" href="#交易怎么才能找到个师父带一带" aria-label="Permalink to &quot;交易怎么才能找到个师父带一带？&quot;">​</a></h1><p>趋势那道光啊</p><p>基本不可能，我的交易技术，除了传授给我儿子，其他人都传不了</p><p>不是我不想教，是实在教不了</p><p>你以为的找个师父带一带，就是把他的交易策略拿来用一用就行了，其实还差得远。老师要教的不仅是交易技术，还有交易理念和交易心态，甚至是要重塑你的世界观价值观，想想这得有多难</p><p>海龟培训班听说过吧。1000多个人面试，只有10个人被选中，且最终能正确领悟到海龟交易技术精髓的寥寥无几</p><p>你说海龟交易技术难吗？其实不难，一页纸就写完了。那为什么大部分人就是学不会呢？其实是思想出了问题</p><p>你希望有人能传授你交易技术，其实是希望有人能拯救你的思想</p><p>世上最难的两件事是：一是把别人口袋里的钱变成自己的，二是改变他人的思想 我要在改变你思想的同时，还要从你口袋里面掏钱，这简直是地狱难度</p><p>所以市面上的所谓交易培训班，也不说一无是处，在交易的不同阶段是会带来一些作用的，但是想靠参加培训班就稳定盈利，百分百是不可能的</p><p>交易该踩的坑一定会踩，只有经历过刻骨铭心的痛，人才会成长，你曾经所犯的那些错误才铸就了现在的你</p><p>与其想找个师父带一带，不如多去找交易高手多交流，其实到了交易的瓶颈期，交易高手的一句话就可以点醒你，比看几十本书都强</p><p>我记得我有一阵子非常的迷惑，就疯狂的刷知乎，翻看我所认为的交易高手的回答和文章，有些人的主页被我来回翻了十几次，终于在某个回答里面的某一句话触动了我，脑子突然一下子就开窍了，就像是一团交织在一起的棉线，突然找到了一个线头，顺着这个线头慢慢往外抽拉，就解开了这个线团</p><p>我是认为有些人根本不适合做交易这一行的，或是脑子不灵光一根筋，或是性格不好情绪不稳定赌性太强，或者太懒不愿意思考，一切拿来主义</p><p>但是有些人确实是有交易天赋的，但是没遇到正确的人，一直在交易的门外徘徊，那么我是很愿意和他进行交流，可能在聊天中我的某句话也能点醒他。正是基于这个目的，我建了两个微信群，一个叫“吹水群”顾名思义就是大家畅所欲言，另一个是“精进群”希望结识一批立志以交易为生的朋友，大家可以聊的更深入一些，互相启发</p><p>我记得天启大烁哥说过一句话，有人问他为什么愿意把自己的交易理念都公开分享出来，不怕知道的人多了方法就失效了吗。他说不懂他在说什么的，即使看了也没用，因为不会去做，能明白他在说什么的，即使不看他的视频，迟早有一天也会在其他地方学到类似的知识，那么他愿意当这个推手。（原话忘了，大概是这个意思）</p><p>我也时常会在群里分享我对于交易的看法，大部分人还是看不懂的，甚至会回怼。我认为这些都没有关系，因为我知道在这个市场上能成功的人不足5%，按照比例群里达到入门标准的人也不会超过5个。但是我还是会愿意分享，希望能给大家埋下一颗种子，说不定哪天有人会因为我的一句话从而改变了他的整个人生，那也是件功德</p><p>但是说让我从头到尾把每个概念都讲清楚，说实话我不愿意也做不到</p>',18)]))}const f=t(r,[["render",_]]);export{m as __pageData,f as default};
